// Generated by ktor-svelte. Do not edit.
export interface ConfirmOptions {
    details?: string;
    confirm?: string;
    cancel?: string;
    danger?: boolean;
}

export const confirmMessages = {
    confirm: 'OK',
    cancel: 'Cancel',
    failed: 'That did not work. Please try again.'
};

const daisy = true;
let dialogCount = 0;

function failureText(error: unknown): string {
    const body = (error as { body?: { message?: unknown } } | null)?.body;
    return typeof body?.message === 'string' && body.message !== '' ? body.message : confirmMessages.failed;
}

function button(label: string, className: string): HTMLButtonElement {
    const node = document.createElement('button');
    node.type = 'button';
    node.className = className;
    node.textContent = label;
    return node;
}

function askInDialog<T>(question: string, action: () => Promise<T>, options: ConfirmOptions): Promise<T | undefined> {
    const dialog = document.createElement('dialog');
    const id = `ktor-svelte-confirm-${++dialogCount}`;
    dialog.className = 'modal';
    dialog.setAttribute('aria-labelledby', id);
    const box = document.createElement('div');
    box.className = 'modal-box';
    const title = document.createElement('h2');
    title.id = id;
    title.className = 'text-lg font-semibold';
    title.textContent = question;
    box.append(title);
    if (options.details) {
        const details = document.createElement('p');
        details.className = 'py-2';
        details.textContent = options.details;
        box.append(details);
    }
    const failure = document.createElement('p');
    failure.className = 'text-error py-2';
    failure.setAttribute('role', 'alert');
    const actions = document.createElement('div');
    actions.className = 'modal-action';
    const cancel = button(options.cancel ?? confirmMessages.cancel, 'btn');
    const confirm = button(options.confirm ?? confirmMessages.confirm, options.danger ? 'btn btn-error' : 'btn btn-primary');
    confirm.setAttribute('data-confirm', '');
    actions.append(cancel, confirm);
    box.append(actions);
    dialog.append(box);

    return new Promise((resolve) => {
        let running = false;
        const finish = (result: T | undefined) => {
            dialog.close();
            dialog.remove();
            resolve(result);
        };
        cancel.addEventListener('click', () => {
            if (!running) finish(undefined);
        });
        dialog.addEventListener('cancel', (event) => {
            event.preventDefault();
            if (!running) finish(undefined);
        });
        confirm.addEventListener('click', async () => {
            if (running) return;
            running = true;
            confirm.disabled = true;
            cancel.disabled = true;
            confirm.setAttribute('aria-busy', 'true');
            failure.remove();
            try {
                finish(await action());
            } catch (error) {
                running = false;
                confirm.disabled = false;
                cancel.disabled = false;
                confirm.removeAttribute('aria-busy');
                failure.textContent = failureText(error);
                box.insertBefore(failure, actions);
            }
        });
        document.body.append(dialog);
        dialog.showModal();
        (options.danger ? cancel : confirm).focus();
    });
}

export function confirmed<T>(question: string, action: () => Promise<T>, options: ConfirmOptions = {}): Promise<T | undefined> {
    if (typeof document === 'undefined') return Promise.resolve(undefined);
    if (daisy && typeof HTMLDialogElement !== 'undefined') return askInDialog(question, action, options);
    const text = options.details ? `${question}\n\n${options.details}` : question;
    return window.confirm(text) ? action() : Promise.resolve(undefined);
}
